// No smart contract required for basic wallet connection

import { ethers } from 'ethers';

// Connect to MetaMask
async function connectWallet() {
  if (typeof window.ethereum !== 'undefined') {
    const provider = new ethers.BrowserProvider(window.ethereum);
    const accounts = await provider.send("eth_requestAccounts", []);
    const signer = await provider.getSigner();
    return { provider, signer, address: accounts[0] };
  }
  throw new Error('MetaMask not installed');
}

// Get wallet balance
async function getBalance(address: string, provider: ethers.Provider) {
  const balance = await provider.getBalance(address);
  return ethers.formatEther(balance);
}`},"smart-contract":{component:Ihe,title:"Smart Contract Basics",description:"Learn the fundamentals of writing and interacting with smart contracts",templateId:"erc20-basic",difficulty:"beginner",tags:["solidity","basics"],contractName:"SimpleContract.sol"},"nft-minter":{component:Lhe,fullStackComponent:Rhe,title:"NFT Minter",description:"Create and mint ERC-721 NFTs with metadata",templateId:"erc721-nft",difficulty:"intermediate",tags:["nft","erc721","ipfs"],contractName:"NFTCollection.sol"},"token-swap":{component:Ohe,fullStackComponent:Dhe,title:"Token Swap DEX",description:"Build a decentralized exchange for token swaps",templateId:"token-swap-dex",difficulty:"advanced",tags:["defi","dex","amm"],contractName:"TokenSwap.sol"},"ai-contract-generator":{component:Fhe,title:"AI Contract Generator",description:"Generate smart contracts using AI prompts",difficulty:"beginner",tags:["ai","generator"],inlineCode:`// AI Contract Generator
