function WalletDetector() {
  const [hasWallet, setHasWallet] = useState(false);

  useEffect(() => {
    // Check if MetaMask is installed
    if (typeof window.ethereum !== 'undefined') {
      console.log('MetaMask is installed!');
      setHasWallet(true);
    }
  }, []);

  return (
    <div>
      {hasWallet ? (
        <p>✅ Wallet detected!</p>
      ) : (
        <p>❌ Please install MetaMask</p>
      )}
    </div>
  );
}

